[CmdletBinding()]
param([string]$RepositoryRoot = (Split-Path -Parent $PSScriptRoot))

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Net.Http

function Get-EnvValue([string]$Path,[string]$Name){$line=Get-Content -LiteralPath $Path -Encoding UTF8|Where-Object {$_ -match "^\s*$([regex]::Escape($Name))\s*="}|Select-Object -First 1;if($null -eq $line){return $null};(($line-replace "^\s*$([regex]::Escape($Name))\s*=",'').Trim()).Trim('"').Trim("'")}
function Read-JsonLines([string]$Path){@(Get-Content -LiteralPath $Path -Encoding UTF8|Where-Object {$_.Trim()}|ForEach-Object {$_|ConvertFrom-Json})}
function Get-WaitSeconds($Headers){try{$value=($Headers.GetValues('retry-after')-join ',');if($value -match '^\s*(\d+)'){return [int]$Matches[1]}}catch{};return 60}
function Invoke-Groq([string]$Key,[string]$Model,[string]$System,[string]$User){$effort=if($Model -like 'qwen/*'){'default'}else{'low'};$body=[ordered]@{model=$Model;reasoning_effort=$effort;temperature=0.1;max_completion_tokens=3500;response_format=@{type='json_object'};messages=@(@{role='system';content=$System},@{role='user';content=$User})}|ConvertTo-Json -Depth 8 -Compress;$client=[System.Net.Http.HttpClient]::new();$client.Timeout=[timespan]::FromSeconds(90);$request=[System.Net.Http.HttpRequestMessage]::new([System.Net.Http.HttpMethod]::Post,'https://api.groq.com/openai/v1/chat/completions');$request.Headers.Authorization=[System.Net.Http.Headers.AuthenticationHeaderValue]::new('Bearer',$Key);$request.Content=[System.Net.Http.StringContent]::new($body,[System.Text.Encoding]::UTF8,'application/json');try{$response=$client.SendAsync($request).GetAwaiter().GetResult();try{[pscustomobject]@{status=[int]$response.StatusCode;headers=$response.Headers;body=$response.Content.ReadAsStringAsync().GetAwaiter().GetResult()}}finally{$response.Dispose()}}catch{[pscustomobject]@{status=599;headers=$null;body=$_.Exception.Message}}finally{$request.Dispose();$client.Dispose()}}
function Get-KbFiles([string]$Path){$files=@{};foreach($file in (Get-ChildItem -LiteralPath $Path -Filter '*.md')){$line=Get-Content -LiteralPath $file.FullName -Encoding UTF8 -TotalCount 8|Where-Object {$_ -match '^topic_id:\s*\d+\s*$'}|Select-Object -First 1;if($line -match '^topic_id:\s*(\d+)\s*$'){$files[[int]$Matches[1]]=$file.FullName}};$files}
function Get-SourceList($Rows){$sources=@{};foreach($row in $Rows){$sources[$row.source_id]=$row.relative_path};(($sources.Keys|Sort-Object|ForEach-Object {"- [$_](../$(([string]$sources[$_]).Replace('\\','/')))"})-join "`n")}
function Write-Document([string]$Path,$Topic,[string]$Body,$Rows){$count=@($Rows|Select-Object -ExpandProperty source_id -Unique).Count;$header="---`ntopic_id: $($Topic.topic_id)`ntitle: $($Topic.topic_title)`nstatus: synthesized`nsource_count: $count`nsource_scope:`n  - data/texts`n  - data/transcripts`n---`n`n# $($Topic.topic_title)`n`n";[System.IO.File]::WriteAllText($Path,$header+$Body.Trim()+"`n`n## Sources`n`n"+(Get-SourceList $Rows)+"`n",[System.Text.UTF8Encoding]::new($false))}

$repo=(Resolve-Path -LiteralPath $RepositoryRoot).Path;$build=Join-Path $repo 'build';$kb=Join-Path $repo 'kb';$key=Get-EnvValue (Join-Path $repo '.env') 'GROQ_API_KEY6';if([string]::IsNullOrWhiteSpace($key)){throw 'Missing GROQ_API_KEY6 in .env.'}
$mapRows=Read-JsonLines (Join-Path $build 'kb-source-map.jsonl');$synthesis=Read-JsonLines (Join-Path $build 'llm-kb-hierarchical-synthesis-checkpoint.jsonl');$checkpointPath=Join-Path $build 'llm-kb-final-repair-checkpoint.jsonl';$done=@{};if(Test-Path -LiteralPath $checkpointPath){foreach($entry in (Read-JsonLines $checkpointPath)){$done[[int]$entry.topic_id]=$entry}};$files=Get-KbFiles $kb;$models=@('openai/gpt-oss-20b','openai/gpt-oss-120b','qwen/qwen3.6-27b')
$system=@'
Return a JSON object only: {"markdown":"..."}. The markdown value must start exactly with "## Overview" and contain exactly these sections in order: Overview, Core ideas, Principles and mental models, Recommended practices, Examples and stories, Tensions and contradictions, Caveats. Include inline [S0001] citations only from the supplied evidence. Do not include analysis, reasoning, <think> tags, a title, YAML, a Sources section, or code fences. Attribute contested statements to the creator; flag speculative health/scientific claims, strongly gendered or misogynistic framing, political claims, and unsafe advice. Do not invent facts.
'@
$writer=[System.IO.StreamWriter]::new($checkpointPath,$true,[System.Text.UTF8Encoding]::new($false))
try{foreach($topicId in @(4)){if($done.ContainsKey($topicId)){continue};$rows=@($mapRows|Where-Object {[int]$_.topic_id -eq $topicId -and $_.assignment_role -eq 'primary'});$topic=$rows[0];$kind=if($topicId -eq 25){'merge'}else{'evidence'};$notes=@($synthesis|Where-Object {[int]$_.topic_id -eq $topicId -and $_.kind -eq $kind}|Sort-Object work_id|ForEach-Object {$_.content});$user="Topic ${topicId}: $($topic.topic_title)`n`nCited evidence notes:`n`n"+($notes-join "`n`n---`n`n");$valid=@($rows|Select-Object -ExpandProperty source_id -Unique);$result=$null;foreach($model in $models){$response=Invoke-Groq $key $model $system $user;if($response.status -eq 429){$wait=Get-WaitSeconds $response.headers;Write-Output "Rate limited on $model for topic $topicId; waiting $wait second(s).";Start-Sleep -Seconds $wait;continue};if($response.status -lt 200 -or $response.status -ge 300){Write-Output "HTTP $($response.status) on $model for topic $topicId; trying next model.";continue};try{$markdown=((((($response.body|ConvertFrom-Json).choices)|Select-Object -First 1).message.content)|ConvertFrom-Json).markdown.Trim();$sections=@('## Overview','## Core ideas','## Principles and mental models','## Recommended practices','## Examples and stories','## Tensions and contradictions','## Caveats');if($markdown -match '<think>' -or $markdown -notmatch '^## Overview'){throw 'Invalid document opening.'};foreach($section in $sections){if($markdown -notmatch [regex]::Escape($section)){throw "Missing $section"}};$citations=@([regex]::Matches($markdown,'\[S\d{4}\]')|ForEach-Object {$_.Value.Trim('[',']')}|Sort-Object -Unique);if($citations.Count -eq 0 -or @($citations|Where-Object {$_ -notin $valid}).Count){throw 'Invalid citations.'};$result=[pscustomobject]@{markdown=$markdown;model=$model};break}catch{Write-Output "Malformed JSON response on $model for topic $topicId; trying next model.";continue}};if($null -eq $result){throw "Could not regenerate topic $topicId with GROQ_API_KEY6."};Write-Document $files[$topicId] $topic $result.markdown $rows;$entry=[ordered]@{topic_id=$topicId;model=$result.model;completed_at=(Get-Date).ToUniversalTime().ToString('o');markdown=$result.markdown};$writer.WriteLine(($entry|ConvertTo-Json -Depth 4 -Compress));$writer.Flush();$done[$topicId]=[pscustomobject]$entry;Write-Output "Regenerated topic $topicId with $($result.model)."}}finally{$writer.Dispose()}
